def assert_response(responseBody, globalParam, statusCode, headers):
    if statusCode != 200 or not isinstance(responseBody, dict) or responseBody.get("code") != 0:
        raise Blocked("TC-124 前提查询失败：GET /rating-categories 应返回 HTTP 200 与业务码 0")
    if not isinstance(responseBody.get("data"), list):
        raise Blocked("TC-124 前提查询失败：GET /rating-categories 应返回分类编码数组")
    if not all(isinstance(item, str) for item in responseBody["data"]):
        raise Blocked("TC-124 前提查询失败：分类编码数组元素应为字符串")
    assert responseBody.get("requestId")
    raise Blocked("TC-124 公开 HTTP 没有重算同一批评级样本的触发接口，重复读取摘要不触发已确认的重算流程；无法构造相同样本重复计算的前提、无法核查计数与评级不增加的规则；查询成功不能代替目标场景通过，源用例结论为阻塞")
